import{_ as r,c as n,o as t,a2 as a}from"./chunks/framework.CIiVzG-O.js";const g=JSON.parse('{"title":"Personnalisation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/customize.md","filePath":"fr/guide/customize.md","lastUpdated":1793163976000}'),i={name:"fr/guide/customize.md"};function s(o,e,l,u,d,c){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="personnalisation" tabindex="-1">Personnalisation <a class="header-anchor" href="#personnalisation" aria-label="Permalink to &quot;Personnalisation&quot;">​</a></h1><p>Rendez NueZip véritablement vôtre en personnalisant votre expérience de gestion d&#39;archives. Ce guide couvre tout ce que vous pouvez personnaliser.</p><h2 id="preferences-generales" tabindex="-1">Préférences générales <a class="header-anchor" href="#preferences-generales" aria-label="Permalink to &quot;Préférences générales&quot;">​</a></h2><p>Ouvrez <strong>NueZip → Réglages</strong> (ou appuyez sur <code>Cmd+,</code>) pour accéder à toutes les options de personnalisation.</p><h3 id="apparence" tabindex="-1">Apparence <a class="header-anchor" href="#apparence" aria-label="Permalink to &quot;Apparence&quot;">​</a></h3><ul><li><strong>Thème</strong> : Choisissez entre Clair, Sombre ou Système (suit l&#39;apparence macOS)</li><li><strong>Style d&#39;icône</strong> : Définissez une icône de barre de menu monochrome ou en couleur</li><li><strong>Langue</strong> : Sélectionnez parmi les langues prises en charge (English, 中文, 日本語, 한국어, et plus)</li></ul><h2 id="valeurs-par-defaut-de-compression" tabindex="-1">Valeurs par défaut de compression <a class="header-anchor" href="#valeurs-par-defaut-de-compression" aria-label="Permalink to &quot;Valeurs par défaut de compression&quot;">​</a></h2><p>Définissez vos valeurs de compression par défaut préférées :</p><table tabindex="0"><thead><tr><th>Réglage</th><th>Options</th><th>Description</th></tr></thead><tbody><tr><td><strong>Format par défaut</strong></td><td>ZIP, 7z, TAR, GZIP, BZIP2, XZ</td><td>Format d&#39;archive pour une compression rapide</td></tr><tr><td><strong>Niveau de compression</strong></td><td>Store, Fast, Normal, Maximum, Ultra</td><td>Compromis entre vitesse et taux</td></tr><tr><td><strong>Chiffrement</strong></td><td>None, AES-128, AES-256</td><td>Chiffrement par défaut pour les archives ZIP/7z</td></tr><tr><td><strong>Taille de volume</strong></td><td>Personnalisé (Mo)</td><td>Taille de fractionnement par défaut pour les archives multi-volumes</td></tr></tbody></table><h3 id="exemple-de-configuration" tabindex="-1">Exemple de configuration <a class="header-anchor" href="#exemple-de-configuration" aria-label="Permalink to &quot;Exemple de configuration&quot;">​</a></h3><p>Pour un usage quotidien :</p><ul><li><strong>Format</strong> : ZIP</li><li><strong>Niveau</strong> : Normal</li><li><strong>Chiffrement</strong> : AES-256 (pour les fichiers sensibles)</li><li><strong>Volume</strong> : Désactivé</li></ul><p>Pour l&#39;archivage :</p><ul><li><strong>Format</strong> : 7-Zip</li><li><strong>Niveau</strong> : Ultra</li><li><strong>Chiffrement</strong> : AES-256</li><li><strong>Volume</strong> : 4,7 Go (pour tenir sur DVD)</li></ul><h2 id="preferences-d-extraction" tabindex="-1">Préférences d&#39;extraction <a class="header-anchor" href="#preferences-d-extraction" aria-label="Permalink to &quot;Préférences d&#39;extraction&quot;">​</a></h2><p>Personnalisez le comportement d&#39;extraction :</p><ul><li><strong>Extraire vers un sous-dossier par défaut</strong> : Crée automatiquement un dossier nommé lors de l&#39;extraction</li><li><strong>Ouvrir le dossier après extraction</strong> : Révèle les contenus extraits dans Finder</li><li><strong>Comportement de remplacement</strong> : Demander, Toujours écraser ou Ignorer les fichiers existants</li><li><strong>Préserver les dates de fichiers</strong> : Conserve les horodatages originaux de l&#39;archive</li></ul><h2 id="extension-finder" tabindex="-1">Extension Finder <a class="header-anchor" href="#extension-finder" aria-label="Permalink to &quot;Extension Finder&quot;">​</a></h2><p>Gérez l&#39;intégration du menu contextuel Finder :</p><ul><li><strong>Activer/Désactiver</strong> : Active ou désactive les éléments du menu au clic droit</li><li><strong>Actions rapides</strong> : Choisissez les actions qui apparaissent dans le menu contextuel <ul><li>Extraire ici</li><li>Extraire vers un dossier</li><li>Compresser en ZIP</li><li>Compresser avec options</li></ul></li></ul><p>Gérez-les dans : <strong>Réglages système → Confidentialité et sécurité → Extensions → Extensions Finder</strong></p><h2 id="icone-de-la-barre-de-menu-zone" tabindex="-1">Icône de la barre de menu (zone) <a class="header-anchor" href="#icone-de-la-barre-de-menu-zone" aria-label="Permalink to &quot;Icône de la barre de menu (zone)&quot;">​</a></h2><p>Personnalisez le panneau de dépôt de la barre de menu :</p><ul><li><strong>Afficher dans la barre de menu</strong> : Active/désactive l&#39;icône de zone</li><li><strong>Fermer automatiquement le panneau</strong> : Ferme le panneau de dépôt après extraction</li><li><strong>Archives récentes</strong> : Nombre d&#39;éléments récents à afficher</li><li><strong>Quitter à la fermeture</strong> : Selon que l&#39;application reste en arrière-plan</li></ul><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><ul><li><strong>Afficher les alertes de fin</strong> : Notifie quand les opérations longues se terminent</li><li><strong>Afficher les alertes d&#39;erreur</strong> : Affiche des notifications pour les opérations échouées</li><li><strong>Son</strong> : Joue un son quand les opérations se terminent</li></ul><h2 id="reglages-generaux" tabindex="-1">Réglages généraux <a class="header-anchor" href="#reglages-generaux" aria-label="Permalink to &quot;Réglages généraux&quot;">​</a></h2><p>Accédez-y dans <strong>Réglages → Général</strong> :</p><ul><li><strong>Langue</strong> : Basculez entre English, 中文, 日本語, et plus</li><li><strong>Lancement à la connexion</strong> : NueZip démarre automatiquement à votre connexion</li><li><strong>Thème</strong> : Mode clair ou sombre (suit le système par défaut)</li><li><strong>Icône de la barre de menu</strong> : Affiche ou masque l&#39;icône de la barre de menu</li></ul><h2 id="conseils" tabindex="-1">Conseils <a class="header-anchor" href="#conseils" aria-label="Permalink to &quot;Conseils&quot;">​</a></h2><ul><li>Définissez une fois vos valeurs de compression favorites pour accélérer l&#39;archivage quotidien</li><li>Activez « Lancement à la connexion » pour que NueZip ne soit qu&#39;à un clic</li><li>Utilisez l&#39;extension Finder pour le flux de travail d&#39;extraction/compression le plus rapide</li><li>Revoyez périodiquement l&#39;accès aux dossiers dans les Réglages système pour garder les choses ordonnées</li></ul>',31)])])}const m=r(i,[["render",s]]);export{g as __pageData,m as default};
